const NEWMEN7={
eagle:{c:{eyeOne:"gray-blue",markings:"an eagle tattoo spread across his back"},
  blurb:"Her wingman: a tall, broad-shouldered aerobatic pilot with a short dark-blond crop, gray-blue eyes, a square jaw, light stubble and an eagle tattoo spread across his back, who flies wingtip to wingtip with her every weekend. All black, a leather jacket, sweatpants, or nothing at all."},
falcon:{c:{eyeOne:"dark brown",markings:"a falcon tattoo across his chest and a scar along his jaw"},
  blurb:"Her rival on the track: a big, broad, scarred motorcycle racer with a black undercut, dark eyes, a short beard and a falcon tattoo across his chest, the only rider she has never managed to leave behind. Leather and chains, battle armor, or bare."},
hawk:{c:{eyeOne:"hazel",markings:"talon-mark scars along one forearm"},
  blurb:"Her falconer: a huge, rugged wildlife ranger with shaggy dark hair, hazel eyes, a thick beard, a hairy chest and talon-mark scars along one forearm, who taught her to fly her first hawk. Flannel and a shearling jacket, or shirtless in worn jeans."},
vulture:{c:{eyeOne:"dark gray",markings:"skull-and-rose tattoos down both arms"},
  blurb:"Her night-shift match: a lean, tattooed restorer of old headstones with a black undercut, dark gray eyes, stubble, skull-and-rose tattoos down both arms and a lopsided grin, who brings her the wildflowers he finds on the cemetery path. A dirt-smudged tank top and tool belt, a battered leather jacket, or nothing."},
osprey:{c:{eyeOne:"warm brown",markings:"a fish-hook tattoo on one forearm"},
  blurb:"Her lakeside chef: a tall, broad-shouldered chef who runs the boathouse kitchen, with tousled dark hair, warm brown eyes, a short beard and a fish-hook tattoo on one forearm, who cooks whatever she catches and saves her the best piece. A crisp white chef's coat and apron, an indigo jacket over a black shirt, or nothing."},
magpie:{c:{eyeOne:"green",markings:"a magpie tattoo on the back of one hand"},
  blurb:"Her partner in crime: a tall, charming jeweler and lockpick with dark tousled hair, green eyes, a neat goatee and a magpie tattoo on one hand, who appraises everything she steals and keeps trying to give her a ring of his own. A shirt, waistcoat and loupe, a long coat and knit scarf, or nothing."},
snowyowl:{c:{eyeOne:"gray",markings:"a star-map tattoo across his back"},
  blurb:"Her fellow stargazer: a tall, gentle astronomer with tousled ash-blond hair, quiet gray eyes behind round glasses, a short neat beard and a star-map tattoo across his back, who sits beside her in silence for hours. A cardigan and henley, a long coat and scarf, or nothing."},
macaw:{c:{eyeOne:"dark brown",markings:"a guitar tattoo on one forearm"},
  blurb:"Her guitarist: a tall, warm-eyed bossa nova guitarist with loose dark curls, dark brown eyes, light stubble and a guitar tattoo on one forearm, who plays every song she wants to sing. A cream cable-knit sweater, a henley with an apron, an open shirt, or nothing."},
cockatoo:{c:{eyeOne:"bright blue",markings:"a sunburst tattoo on one shoulder"},
  blurb:"Her surf lifesaver: a towering, sun-bronzed surf lifesaver with shaggy sun-bleached hair, bright blue eyes, light stubble and a sunburst tattoo, who dances with her at every beach party even though he can't dance. An open white linen shirt and shell necklace, or swim trunks."},
birdofparadise:{c:{eyeOne:"dark brown",markings:"a plume tattoo over his heart"},
  blurb:"Her dance partner: a tall, lithe tango lead with slicked-back black hair, smoldering dark eyes, a clean-shaven, chiseled face and a plume tattoo over his heart, who has never once let her fall. A white tuxedo, an open silk shirt, or nothing."},
kingfisher:{c:{eyeOne:"dark brown",markings:"a wave tattoo along his ribs"},
  blurb:"Her cliff diver: a tanned, ripped cliff diver with tousled black hair, dark eyes, a cocky grin, light stubble and a wave tattoo along his ribs, who dives off every rock she dares him to. An open shirt and board shorts, or just the trunks."}};

